// Requirement #32 (unlink a repo): the vault-history-deletion half. Lists
// projects/<name>/** the same way vaultSync.ts does (recursive tree
// listing, filtered by prefix), then deletes each file. This is a live
// mutation of the vault repo, not the local sync cache, so it's a
// sibling module rather than an addition to vaultSync.ts.
const VAULT_BRANCH = "main";
// No-ops cleanly (nothing to delete) if the project has no vault files at
// all — not treated as an error.
async function deleteVaultProject(octokit, { owner, repo }, projectName) {
    const prefix = `projects/${projectName}/`;
    const { data } = await octokit.rest.git.getTree({
        owner,
        repo,
        tree_sha: VAULT_BRANCH,
        recursive: "1",
    });
    const files = data.tree.filter((entry) => entry.type === "blob" && !!entry.path && !!entry.sha && entry.path.startsWith(prefix));
    // Sequential, not Promise.all: each delete is its own commit on the
    // vault's main branch — racing commits on the same branch means the
    // second one loses with a sha-conflict error (the exact bug already
    // hit and fixed in wizardRepoLinker.ts's linkRepo()).
    for (const file of files) {
        await octokit.rest.repos.deleteFile({
            owner,
            repo,
            path: file.path,
            message: `Remove ${file.path} (Devlore setup wizard — unlink)`,
            sha: file.sha,
        });
    }
}
